    ok("!! the scales in the references record and in a circuit's record are scalesOf(the task's training dives), not the unit scales (re-derived here, and not all 1)", V.SENSES.every((k) => near(recs[0].scales[k], want[k], 1e-12) && near(recs[1].scales[k], want[k], 1e-12)) && V.SENSES.some((k) => want[k] !== 1));
