    const costE = rE.cost, rs = H.REFLEXES.map((R) => ({ name: R.name, score: sets.train.reduce((a, dv) => a + H.run(H.reflex(AP, R), dv.sc, { disturb: H.hazardDisturbance(dv, 0) }).score, 0) / sets.train.length })), bestR = rs.reduce((a, b) => (b.score > a.score ? b : a));
    ok("!! the reflex row of the references record is re-derived: the best of the four hand reflexes on the training dives, and the share of the cost it wins back ((best - disturbed autopilot) / cost)", rE.reflex.best === bestR.name && near(rE.reflex.recovered, (bestR.score - rE.disturbedTrain) / costE, 1e-9) && rE.reflex.recovered > 0.5 && rE.reflex.recovered < 1.0001);
