    const stubTasks = { selfTestRunner: () => ({ n: 12, bad: ["nominal 3"] }), selfTestSigns: () => [["a sign", false], ["fine", true]], selfTestTrigger: () => ({ a: true, b: false, c: true, n: 40 }) };
